package com.varma.aiinterviewplatform.service;

import com.varma.aiinterviewplatform.entity.Question;
import org.springframework.stereotype.Component;

import java.time.Instant;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Temporary in-memory storage for questions generated by Gemini.
 * Questions are cached per user and test configuration.
 * They are saved permanently only when the user starts the test.
 */
@Component
public class QuestionPreparationCache {

    private static final long CACHE_LIFETIME_SECONDS = 30 * 60;

    private final ConcurrentHashMap<String, PreparationEntry> cache =
            new ConcurrentHashMap<>();

    public enum Status {
        PREPARING,
        READY,
        FAILED
    }

    public static class PreparationEntry {

        private volatile Status status;
        private volatile List<Question> questions;
        private volatile String errorMessage;
        private final Instant createdAt;

        public PreparationEntry() {
            this.status = Status.PREPARING;
            this.createdAt = Instant.now();
        }

        public Status getStatus() {
            return status;
        }

        public List<Question> getQuestions() {
            return questions;
        }

        public String getErrorMessage() {
            return errorMessage;
        }

        public Instant getCreatedAt() {
            return createdAt;
        }

        public void markReady(List<Question> questions) {
            if (questions == null || questions.isEmpty()) {
                throw new IllegalArgumentException(
                        "Generated questions cannot be empty.");
            }
            this.questions = List.copyOf(questions);
            this.status = Status.READY;
        }

        public void markFailed(String message) {
            this.errorMessage = message;
            this.status = Status.FAILED;
        }
    }

    public PreparationEntry create(String key) {
        PreparationEntry entry = new PreparationEntry();
        cache.put(key, entry);
        return entry;
    }

    public PreparationEntry get(String key) {
        removeExpiredEntries();
        return cache.get(key);
    }

    /**
     * Return ready questions without deleting the cache entry.
     * TestCenterService removes the entry after the database transaction commits.
     */
    public List<Question> getReadyQuestions(String key) {
        PreparationEntry entry = get(key);

        if (entry == null) {
            throw new IllegalStateException(
                    "Questions are not prepared. Please prepare your test again.");
        }

        if (entry.getStatus() == Status.PREPARING) {
            throw new IllegalStateException(
                    "Questions are still being generated. Please wait.");
        }

        if (entry.getStatus() == Status.FAILED) {
            throw new IllegalStateException(
                    entry.getErrorMessage() == null
                            ? "Question generation failed. Please try again."
                            : entry.getErrorMessage());
        }

        List<Question> questions = entry.getQuestions();
        if (questions == null || questions.isEmpty()) {
            throw new IllegalStateException(
                    "Prepared questions are unavailable. Please prepare your test again.");
        }

        return questions;
    }

    public void remove(String key) {
        cache.remove(key);
    }

    private void removeExpiredEntries() {
        Instant expiryTime = Instant.now()
                .minusSeconds(CACHE_LIFETIME_SECONDS);

        cache.entrySet().removeIf(entry ->
                entry.getValue().getCreatedAt().isBefore(expiryTime));
    }
}
